import numpy as np

def r(x):
    # Transforms x to sqrt(x), which is greater than x for x in (0,1).
    # This increases the magnitude of the initial conditions, expecting
    # the final state norm to increase due to the non-linear expansion.
    return np.sqrt(x)

def R(y_orig, y_new):
    # Validity check: ensures outputs are finite numbers.
    # Returns False for NaN or Inf pairs, which are treated as penalties.
    return np.isfinite(y_orig) and np.isfinite(y_new)
